#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>

int sum_in_child(const int *values, int n, long *result) {
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        return -1;
    }

    pid_t pid = fork();
    if (pid == -1) {
        close(pipefd[0]);
        close(pipefd[1]);
        return -1;
    }

    if (pid == 0) {
        /* Child process */
        close(pipefd[0]); /* Close read end */

        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += values[i];
        }

        /* Write the sum to the pipe */
        ssize_t bytes_written = write(pipefd[1], &sum, sizeof(long));
        if (bytes_written != sizeof(long)) {
            close(pipefd[1]);
            _exit(1);
        }

        close(pipefd[1]);
        _exit(0);
    }

    /* Parent process */
    close(pipefd[1]); /* Close write end */

    /* Read the sum from the pipe */
    ssize_t bytes_read = read(pipefd[0], result, sizeof(long));
    if (bytes_read != sizeof(long)) {
        close(pipefd[0]);
        /* Wait for child to clean up */
        int status;
        waitpid(pid, &status, 0);
        return -1;
    }

    close(pipefd[0]);

    /* Wait for child to finish */
    int status;
    if (waitpid(pid, &status, 0) == -1) {
        return -1;
    }

    /* Check if child exited with status 0 */
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        return -1;
    }

    return 0;
}
