import java.util.*;
import java.util.stream.*;

public class Report {

    public record Student(String name, String group, java.util.List<Integer> grades) {}

    public static java.util.Map<String, Double> averageByGroup(java.util.List<Student> students) {
        return students.stream()
                .filter(s -> s.grades() != null && !s.grades().isEmpty())
                .collect(Collectors.groupingBy(
                        Student::group,
                        Collectors.averagingDouble(s -> s.grades().stream()
                                .mapToInt(Integer::intValue)
                                .average()
                                .orElse(0.0))
                ));
    }

    public static java.util.List<String> topStudents(java.util.List<Student> students, int n) {
        return students.stream()
                .filter(s -> s.grades() != null && !s.grades().isEmpty())
                .sorted(Comparator.comparing((Student s) -> s.grades().stream()
                                .mapToInt(Integer::intValue)
                                .average()
                                .orElse(0.0), Comparator.reverseOrder())
                        .thenComparing(Student::name))
                .limit(n)
                .map(Student::name)
                .collect(Collectors.toList());
    }

    public static java.util.Optional<Student> best(java.util.List<Student> students, String group) {
        return students.stream()
                .filter(s -> group.equals(s.group()) && s.grades() != null && !s.grades().isEmpty())
                .max(Comparator.comparingDouble(s -> s.grades().stream()
                        .mapToInt(Integer::intValue)
                        .average()
                        .orElse(0.0)));
    }
}
