#ifndef SHAPE_H
#define SHAPE_H

#include <memory>
#include <string>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
#include <sstream>
#include <stdexcept>
#include <iostream>

class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;
    virtual std::string name() const = 0;
    virtual std::unique_ptr<Shape> clone() const = 0;
};

class Circle : public Shape {
private:
    double r_;
    static constexpr double pi = 3.14159265358979;
public:
    explicit Circle(double r) : r_(r) {
        if (r <= 0) {
            throw std::invalid_argument("Radius must be positive");
        }
    }
    double area() const override {
        return pi * r_ * r_;
    }
    std::string name() const override {
        return "circle";
    }
    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<Circle>(*this);
    }
};

class Rect : public Shape {
private:
    double w_;
    double h_;
public:
    Rect(double w, double h) : w_(w), h_(h) {
        if (w <= 0 || h <= 0) {
            throw std::invalid_argument("Width and height must be positive");
        }
    }
    double area() const override {
        return w_ * h_;
    }
    std::string name() const override {
        return "rect";
    }
    std::unique_ptr<Shape> clone() const override {
        return std::make_unique<Rect>(*this);
    }
};

class Scene {
private:
    std::vector<std::unique_ptr<Shape>> shapes_;

public:
    Scene() = default;

    Scene(const Scene& other) {
        for (const auto& s : other.shapes_) {
            shapes_.push_back(s->clone());
        }
    }

    Scene& operator=(const Scene& other) {
        if (this != &other) {
            shapes_.clear();
            for (const auto& s : other.shapes_) {
                shapes_.push_back(s->clone());
            }
        }
        return *this;
    }

    void add(std::unique_ptr<Shape> s) {
        if (!s) {
            throw std::invalid_argument("Shape cannot be nullptr");
        }
        shapes_.push_back(std::move(s));
    }

    std::size_t size() const {
        return shapes_.size();
    }

    double total_area() const {
        double total = 0.0;
        for (const auto& s : shapes_) {
            total += s->area();
        }
        return total;
    }

    std::string largest() const {
        if (shapes_.empty()) {
            throw std::runtime_error("Scene is empty");
        }
        const Shape* largest_shape = shapes_[0].get();
        for (std::size_t i = 1; i < shapes_.size(); ++i) {
            if (shapes_[i]->area() > largest_shape->area()) {
                largest_shape = shapes_[i].get();
            }
        }
        return largest_shape->name();
    }
};

std::ostream& operator<<(std::ostream& os, const Scene& scene) {
    if (scene.size() == 0) {
        return os;
    }

    struct ShapeInfo {
        std::string name;
        double area;
    };

    std::vector<ShapeInfo> info_list;
    info_list.reserve(scene.size());
    for (const auto& s : scene.shapes_) {
        info_list.push_back({s->name(), s->area()});
    }

    std::sort(info_list.begin(), info_list.end(),
              [](const ShapeInfo& a, const ShapeInfo& b) {
                  return a.area < b.area;
              });

    os << std::fixed << std::setprecision(2);
    for (std::size_t i = 0; i < info_list.size(); ++i) {
        if (i > 0) {
            os << " ";
        }
        os << info_list[i].name << ":" << info_list[i].area;
    }

    return os;
}

